def visible(value, limit=8192):
    label = text(value, limit)
    raw = label.encode('ascii')
    if not raw or any(byte < 0x21 or byte > 0x7e for byte in raw):
        raise InputError('expected identity')
    return label


class Budgets:
    __slots__ = ('items', 'pairs')

    def __init__(self):
        self.items = 0
        self.pairs = 0

    def take_items(self, count):
        self.items += count
        if self.items > MAX_ITEMS:
            raise InputError('combined item budget')

    def take_pairs(self, count):
        self.pairs += count
        if self.pairs > MAX_PAIRS:
            raise InputError('combined header pair budget')


def compile_expect(raw):
    exact(raw, EXPECT_KEYS)
    out = {}
    for key in EXPECT_KEYS:
        out[key] = visible(raw[key])
    if not TOKEN.fullmatch(out['method'].encode('ascii')):
        raise InputError('expected method token')
    return out


